import{_ as n,o as i,c as a,ai as l}from"./chunks/framework.BxxKhjs3.js";const g=JSON.parse("{\"title\":\"HarmonyOS 列表操作实战指南\",\"description\":\"\",\"frontmatter\":{},\"headers\":[],\"relativePath\":\"HarmonyOS 最佳实践/07-常见列表操作/07-常见列表操作.md\",\"filePath\":\"HarmonyOS 最佳实践/07-常见列表操作/07-常见列表操作.md\",\"lastUpdated\":1750695195000,\"__rawMarkdown\":\"# HarmonyOS 列表操作实战指南\\n\\n> 📚 **写给初学者的话**：如果你刚开始学习 HarmonyOS 开发，不用担心！这篇文章会用最简单的方式带你掌握列表操作的核心技能。我们会从最基础的概念开始，一步步构建出复杂的列表功能。\\n\\n## 📖 开始之前：什么是列表？\\n\\n### 🤔 先从生活中的例子说起\\n\\n在开始学习代码之前，让我们先想想生活中的\\\"列表\\\"：\\n\\n- 📝 购物清单：一行行写着要买的东西\\n- 📞 手机通讯录：一个个联系人按顺序排列\\n- 🎵 音乐播放列表：一首首歌曲排成队\\n\\n在 APP 开发中，**列表**就是把这些信息在手机屏幕上\\\"一行一行\\\"地展示出来。\\n\\n### 📱 列表在 APP 中长什么样？\\n\\n打开你的手机，你会发现列表无处不在：\\n\\n- **微信**：聊天记录就是一个列表，每条消息占一行\\n- **淘宝**：商品展示就是列表，每个商品占一行或一块区域\\n- **音乐 APP**：歌曲列表、播放列表都是典型的列表\\n\\n### ✨ 为什么列表这么重要？\\n\\n**对用户来说：**\\n\\n- 📱 **看得清楚**：信息整整齐齐，不会眼花缭乱\\n- 🔍 **找得容易**：可以快速扫视，找到想要的内容\\n- ⚡ **用得舒服**：符合从上到下的阅读习惯\\n- 📜 **装得下**：屏幕放不下的内容可以滑动查看\\n\\n**对开发者来说：**\\n\\n- 🛠️ **开发效率高**：HarmonyOS 提供了强大的列表组件\\n- 🎨 **样式灵活**：可以做出各种美观的效果\\n- 🚀 **性能优秀**：系统自动优化，即使数据很多也很流畅\\n\\n## 🔧 HarmonyOS 中的列表技术\\n\\n### 🧱 核心组件介绍\\n\\n想象一下搭积木：我们用几种基本的\\\"积木块\\\"就能搭出各种复杂的列表。\\n\\n**基础积木（组件）：**\\n\\n| 组件名称          | 作用       | 生活中的比喻                       | 官方文档                                                                                                    |\\n| ----------------- | ---------- | ---------------------------------- | ----------------------------------------------------------------------------------------------------------- |\\n| **List**          | 列表容器   | 就像一个大盒子，装下所有的列表内容 | [📚 查看文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list)          |\\n| **ListItem**      | 单个列表项 | 盒子里的每一个小格子，放一条信息   | [📚 查看文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-listitem)      |\\n| **ListItemGroup** | 列表分组   | 把相关的小格子归类到一起           | [📚 查看文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-listitemgroup) |\\n\\n**📐 组件关系图：**\\n\\n```\\nList (大盒子 - 整个列表)\\n├── ListItem (格子1 - 第一条信息)\\n├── ListItem (格子2 - 第二条信息)\\n├── ListItemGroup (分组盒子)\\n│   ├── ListItem (分组内的格子1)\\n│   └── ListItem (分组内的格子2)\\n└── ListItem (格子N - 最后一条信息)\\n```\\n\\n### 🎯 学习路线图\\n\\n> 💡 **学习建议**：建议按照从简单到复杂的顺序学习，每个场景都建议动手实践一遍！\\n\\n| 难度等级 | 学习内容                          | 适合人群         | 预计学习时间 |\\n| -------- | --------------------------------- | ---------------- | ------------ |\\n| ⭐       | [多类型列表项](#多类型列表项场景) | 刚接触列表开发   | 2-3 小时     |\\n| ⭐⭐     | [Tabs 吸顶效果](#tabs-吸顶场景)   | 有基础列表经验   | 1-2 小时     |\\n| ⭐⭐⭐   | [分组吸顶](#分组吸顶场景)         | 想做通讯录类应用 | 2-3 小时     |\\n| ⭐⭐⭐⭐ | [二级联动](#二级联动场景)         | 想做电商分类页面 | 3-4 小时     |\\n\\n**每个场景包含：**\\n\\n- 🎭 **场景展示**：看看最终要做成什么样子\\n- 🔍 **原理解析**：用最简单的话解释技术原理\\n- 👨‍💻 **代码实战**：一步步跟着做，每段代码都有详细注释\\n- 🎬 **效果预览**：看看我们的成果\\n- 💡 **扩展思考**：举一反三，应用到其他场景\\n\\n### 🚀 开始前的准备\\n\\n**环境要求：**\\n\\n- ✅ 已安装 DevEco Studio\\n- ✅ 已创建 HarmonyOS 项目\\n- ✅ 对 ArkTS 语法有基本了解\\n\\n**如果你还没准备好，建议先：**\\n\\n1. 📖 阅读[HarmonyOS 官方入门教程](https://developer.huawei.com/consumer/cn/training/course/slightMooc/C101667364948559963)\\n2. 🛠️ 跟着[官方 Quick Start](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/start-overview)搭建开发环境\\n\\n## 场景一：多类型列表项 ⭐\\n\\n> 🎯 **学习目标**：掌握在一个列表中展示不同类型内容的技能，做出像电商首页那样的丰富界面\\n\\n### 🤔 什么是多类型列表项？\\n\\n**先从熟悉的 APP 说起：**\\n\\n打开你手机上的淘宝或京东，你会发现首页是这样的：\\n\\n1. 🔍 最顶部：搜索框\\n2. 🖼️ 中间：轮播广告图片\\n3. 🎯 下面：功能按钮（天猫超市、聚划算等）\\n4. 📱 再下面：商品推荐列表\\n\\n**神奇的地方在于**：这些完全不同的内容（搜索框、图片、按钮、列表）都在同一个可以滚动的页面里！\\n\\n这就是\\\"多类型列表项\\\"——一个列表容器里装着各种不同类型的内容。\\n\\n### 🏆 为什么要学这个？\\n\\n**实际开发中超级常用：**\\n\\n- 🏪 **电商 APP**：首页几乎都是这种设计\\n- 📰 **新闻 APP**：头条 + 导航 + 新闻列表\\n- 🎵 **音乐 APP**：推荐歌单 + 排行榜 + 新歌\\n- 🏠 **几乎所有 APP 首页**：都需要展示丰富的内容类型\\n\\n**学会了你就能做：**\\n\\n- ✅ 复杂的首页界面\\n- ✅ 丰富的内容展示\\n- ✅ 用户体验良好的滚动效果\\n- ✅ 下拉刷新、上拉加载等高级功能\\n\\n### 🎯 本例效果预览\\n\\n我们将实现一个旅游应用的首页，包含：\\n\\n1. **顶部搜索框**：固定在页面顶部\\n2. **轮播图区域**：展示热门景点图片\\n3. **功能网格**：快速入口（如\\\"门票\\\"、\\\"酒店\\\"等）\\n4. **推荐内容**：景点推荐列表\\n5. **交互功能**：下拉刷新、上拉加载、标题吸顶\\n\\n|\\n页面整体结构图\\n\\n|\\n\\n页面效果图\\n\\n| |\\n| |\\n\\n|\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165821.60051003176734729980242660374115:50001231000000:2800:952C869F3BFD2FC0748823BBC2802E9112218FE78BF13CCC763BDAEA1E2E5716.png)\\n\\n|\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165822.02196712916895667066031953474498:50001231000000:2800:225020A5502CE216E5ED9A65CE12CD1E5E2AB43501F0147B2EF4085D535E5B6E.png)\\n\\n|\\n\\n### 🔍 实现原理（简单易懂版）\\n\\n**核心思路：像搭积木一样组装界面**\\n\\n想象你有一个神奇的大盒子（List），可以往里面放各种不同的\\\"积木\\\"（ListItem）：\\n\\n```\\n🗃️ List (神奇大盒子)\\n├── 🧩 ListItem (积木1：搜索框)\\n├── 🧩 ListItem (积木2：轮播图)\\n├── 🧩 ListItem (积木3：功能按钮网格)\\n├── 🧩 ListItem (积木4：推荐标题)\\n├── 🧩 ListItem (积木5：推荐内容1)\\n├── 🧩 ListItem (积木6：推荐内容2)\\n└── 🧩 ...更多积木\\n```\\n\\n**🛠️ 需要用到的工具（组件）：**\\n\\n| 工具名称     | 用途         | 生活中的比喻                 | 何时使用           |\\n| ------------ | ------------ | ---------------------------- | ------------------ |\\n| **Refresh**  | 下拉刷新容器 | 像给手机\\\"拉一下\\\"就能更新内容 | 需要下拉刷新功能时 |\\n| **List**     | 列表主容器   | 装所有内容的大盒子           | 几乎总是需要       |\\n| **ListItem** | 单个列表项   | 盒子里的每个小格子           | 每一块内容都需要   |\\n| **Swiper**   | 轮播图组件   | 可以左右滑动的相册           | 需要图片轮播时     |\\n| **Grid**     | 网格布局     | 像九宫格一样排列的格子       | 需要整齐排列按钮时 |\\n\\n**🔄 用户操作流程：**\\n\\n```\\n用户下拉页面 🔽\\n     ↓\\n触发刷新事件 🔄\\n     ↓\\n模拟获取新数据 📡\\n     ↓\\n更新界面内容 ✨\\n\\n用户滚动到底部 📜\\n     ↓\\n触发加载更多 ⬆️\\n     ↓\\n追加新内容 ➕\\n```\\n\\n> 💡 **新手提示**：不用一次性掌握所有组件，我们会一步步来，每个步骤都有详细说明！\\n\\n### 👨‍💻 动手实践：一步步实现\\n\\n> 💡 **开始前的提醒**：建议在 DevEco Studio 中新建一个项目，跟着教程一步步敲代码，这样学习效果最好！\\n\\n#### 🔧 步骤一：搭建搜索框（难度：⭐）\\n\\n**🎯 目标：** 做一个像淘宝首页那样的搜索框\\n\\n**📝 学习要点：**\\n\\n- 了解 Row 布局（水平排列）\\n- 学会使用 Image 和 TextInput 组件\\n- 掌握基本的样式设置\\n\\n**💭 思路：** 搜索框 = 搜索图标 + 输入框，用 Row 把它们横向排列\\n\\n```typescript\\n// 🏗️ 搜索框组件 - 新手友好版\\n@Component\\nstruct SearchHeader {\\n  build() {\\n    Row() {  // Row是水平布局，让内容从左到右排列\\n      // 🔍 搜索图标\\n      Image($r('app.media.search_icon'))\\n        .width(20)    // 图标宽度20像素\\n        .height(20)   // 图标高度20像素\\n\\n      // 📝 搜索输入框\\n      TextInput({ placeholder: '搜索景点、酒店...' })\\n        .layoutWeight(1)    // 占据剩余所有空间\\n        .margin({ left: 10 }) // 左边距10像素，和图标保持距离\\n    }\\n    .padding(16)            // 整个搜索框内边距16像素\\n    .backgroundColor(Color.White)  // 白色背景\\n  }\\n}\\n```\\n\\n**📖 代码解释：**\\n\\n- `Row()`：让里面的内容水平排列（从左到右）\\n- `Image()`：显示搜索图标\\n- `TextInput()`：用户可以输入文字的框\\n- `layoutWeight(1)`：让输入框占据除图标外的所有空间\\n- `padding(16)`：内容和边框之间留 16 像素的空隙\\n\\n**✨ 效果预览：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165822.23123068689975124694076234541907:50001231000000:2800:264D367D0D08ACF27FCE6F986C8951003B950C6229CDE21F436E34CA79C75518.png)\\n\\n> 🎉 **恭喜！** 你已经学会了基础的组件使用和布局！接下来我们要做更酷的轮播图...\\n\\n#### 📸 步骤二：制作轮播图（难度：⭐⭐）\\n\\n**🎯 目标：** 做一个可以自动播放的图片轮播，就像电商 APP 首页的广告图\\n\\n**📝 学习要点：**\\n\\n- 掌握 Swiper 组件的基本用法\\n- 学会使用 ForEach 循环渲染数据\\n- 了解自动播放和指示器设置\\n\\n**💭 思路：** 轮播图 = 多张图片 + 自动切换 + 底部小圆点\\n\\n**🔧 实现代码：**\\n\\n```typescript\\n// 📸 轮播图组件 - 带详细注释\\nListItem() {  // 这是List里的一个项目，专门放轮播图\\n  Swiper() {  // Swiper让图片可以左右滑动\\n    // 🔄 ForEach循环：把数组里的每张图片都显示出来\\n    ForEach(this.bannerImages, (item: string) => {\\n      Image(item)               // 显示图片\\n        .width('100%')          // 宽度占满整个容器\\n        .height(200)            // 高度固定200像素\\n        .borderRadius(8)        // 圆角8像素，看起来更美观\\n    })\\n  }\\n  .autoPlay(true)               // ✨ 自动播放（像电视换台一样）\\n  .interval(3000)               // ⏰ 每3秒自动切换一次\\n  .indicator(true)              // 🔵 显示底部小圆点（告诉用户当前看的是第几张）\\n  .padding(16)                  // 四周留16像素空隙\\n}\\n```\\n\\n**📊 数据准备：**\\n\\n```typescript\\n// 📷 轮播图片数组 - 你可以换成自己的图片\\n@State bannerImages: string[] = [\\n  'https://example.com/banner1.jpg',  // 第一张图\\n  'https://example.com/banner2.jpg',  // 第二张图\\n  'https://example.com/banner3.jpg'   // 第三张图\\n]\\n```\\n\\n**📖 代码解释：**\\n\\n- `Swiper()`：神奇的轮播容器，让内容可以左右滑动\\n- `ForEach()`：循环渲染，有几张图片就显示几张\\n- `autoPlay(true)`：开启自动播放模式\\n- `interval(3000)`：3000 毫秒 = 3 秒，设置切换间隔\\n- `indicator(true)`：显示底部的小圆点导航\\n\\n**✨ 效果预览：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165822.55285279733896861556050935948982:50001231000000:2800:B8F7DBE199669C4B6E6FEDE4FD5AFB69695DC4F79DCF385D80E089E1476B5B91.png)\\n\\n> 💡 **小贴士**：如果图片加载不出来，检查一下网络地址是否正确，或者先用本地图片测试\\n\\n#### 🎯 步骤三：制作功能网格（难度：⭐⭐）\\n\\n**🎯 目标：** 做一个像手机桌面那样的图标网格，放各种功能入口\\n\\n**📝 学习要点：**\\n\\n- 掌握 Grid 网格布局\\n- 理解行列模板的设置\\n- 学会处理点击事件\\n\\n**💭 思路：** 网格 = 多个按钮整齐排列，就像九宫格游戏\\n\\n**🔧 实现代码：**\\n\\n```typescript\\n// 🎯 功能网格组件 - 新手详解版\\nListItem() {  // 又是List里的一个项目\\n  Grid() {    // Grid是网格布局，让内容像表格一样排列\\n    // 🔄 循环显示每个功能按钮\\n    ForEach(this.functionList, (item: FunctionItem) => {\\n      GridItem() {  // 网格中的一个格子\\n        Column() {  // Column是垂直布局，图标在上，文字在下\\n          // 🎨 功能图标\\n          Image(item.icon)\\n            .width(40)              // 图标宽40像素\\n            .height(40)             // 图标高40像素\\n\\n          // 📝 功能名称\\n          Text(item.title)\\n            .fontSize(12)           // 文字大小12像素\\n            .margin({ top: 8 })     // 和图标保持8像素距离\\n        }\\n        .justifyContent(FlexAlign.Center)  // 内容居中显示\\n      }\\n      .onClick(() => {\\n        // 🖱️ 点击事件：用户点击按钮时会执行这里的代码\\n        console.log(`用户点击了${item.title}`)\\n        // 这里可以添加跳转页面、弹窗等功能\\n      })\\n    })\\n  }\\n  .columnsTemplate('1fr 1fr 1fr 1fr')  // 📐 4列，每列宽度相等\\n  .rowsTemplate('1fr 1fr')             // 📐 2行，每行高度相等\\n  .height(160)                         // 整个网格高度160像素\\n  .padding(16)                         // 四周留16像素空隙\\n}\\n```\\n\\n**📊 数据准备：**\\n\\n```typescript\\n// 🛠️ 功能列表数据\\ninterface FunctionItem {\\n  icon: string    // 图标地址\\n  title: string   // 功能名称\\n}\\n\\n@State functionList: FunctionItem[] = [\\n  { icon: 'app.media.hotel_icon', title: '酒店' },\\n  { icon: 'app.media.ticket_icon', title: '门票' },\\n  { icon: 'app.media.food_icon', title: '美食' },\\n  { icon: 'app.media.car_icon', title: '租车' },\\n  { icon: 'app.media.guide_icon', title: '导游' },\\n  { icon: 'app.media.more_icon', title: '更多' }\\n]\\n```\\n\\n**📖 代码解释：**\\n\\n- `Grid()`：网格布局容器，像 Excel 表格一样\\n- `GridItem()`：网格中的每一个格子\\n- `Column()`：垂直布局，让图标和文字上下排列\\n- `columnsTemplate('1fr 1fr 1fr 1fr')`：分成 4 列，每列宽度相等\\n- `rowsTemplate('1fr 1fr')`：分成 2 行，每行高度相等\\n- `onClick()`：点击事件处理函数\\n\\n**✨ 效果预览：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165822.60767522191044372351924427186069:50001231000000:2800:A9412894CCC5D557EDA688FF8253C952A638CE4C96714AC7F0C1922C589E7003.png)\\n\\n> 🎮 **互动体验**：运行代码后试着点击不同的按钮，看看控制台的输出信息\\n\\n#### 步骤 4：创建推荐内容列表\\n\\n**目标：** 添加可滚动的推荐内容列表\\n\\n**关键点：**\\n\\n- 先添加一个标题 ListItem（设置 sticky 属性）\\n- 然后添加多个内容 ListItem\\n- 每个内容项包含图片、标题、描述等\\n\\n```typescript\\n// 推荐标题（吸顶效果）\\nListItem() {\\n  Text('推荐景点')\\n    .fontSize(18)\\n    .fontWeight(FontWeight.Bold)\\n    .padding(16)\\n    .backgroundColor(Color.White)\\n}\\n.sticky(Sticky.Normal) // 关键：设置吸顶效果\\n\\n// 推荐内容项\\nForEach(this.recommendList, (item: RecommendItem) => {\\n  ListItem() {\\n    Row() {\\n      Image(item.image)\\n        .width(80)\\n        .height(80)\\n        .borderRadius(8)\\n\\n      Column() {\\n        Text(item.title)\\n          .fontSize(16)\\n          .fontWeight(FontWeight.Medium)\\n        Text(item.description)\\n          .fontSize(14)\\n          .fontColor(Color.Gray)\\n          .margin({ top: 4 })\\n        Text(`¥${item.price}`)\\n          .fontSize(16)\\n          .fontColor(Color.Red)\\n          .margin({ top: 8 })\\n      }\\n      .alignItems(HorizontalAlign.Start)\\n      .margin({ left: 12 })\\n      .layoutWeight(1)\\n    }\\n    .padding(16)\\n    .alignItems(VerticalAlign.Top)\\n  }\\n})\\n```\\n\\n**实现效果：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165822.82461337837184865708833886908179:50001231000000:2800:266A6373EE87A80983FEBE4907EED39A0AE65EF23C9A7427C6FA3716D8981ED7.png)\\n\\n#### 步骤 5：添加刷新和加载功能\\n\\n**目标：** 实现下拉刷新和上拉加载更多功能\\n\\n**关键点：**\\n\\n- 用 Refresh 组件包裹整个 List\\n- 添加 onRefreshing 回调处理下拉刷新\\n- 添加 onReachEnd 回调处理上拉加载\\n\\n```typescript\\n// 完整页面结构\\n@Component\\nstruct HomePage {\\n  @State isRefreshing: boolean = false\\n  @State recommendList: RecommendItem[] = []\\n\\n  build() {\\n    Column() {\\n      // 顶部搜索框（固定）\\n      SearchHeader()\\n\\n      // 可刷新的内容区域\\n      Refresh({ refreshing: this.isRefreshing }) {\\n        List() {\\n          // 轮播图\\n          ListItem() { /* Swiper内容 */ }\\n\\n          // 功能网格\\n          ListItem() { /* Grid内容 */ }\\n\\n          // 推荐标题（吸顶）\\n          ListItem() { /* 标题内容 */ }\\n          .sticky(Sticky.Normal)\\n\\n          // 推荐列表\\n          ForEach(this.recommendList, (item) => {\\n            ListItem() { /* 推荐项内容 */ }\\n          })\\n        }\\n        .onReachEnd(() => {\\n          // 上拉加载更多\\n          this.loadMoreData()\\n        })\\n      }\\n      .onRefreshing(() => {\\n        // 下拉刷新\\n        this.refreshData()\\n      })\\n    }\\n  }\\n\\n  // 刷新数据\\n  refreshData() {\\n    this.isRefreshing = true\\n    // 模拟网络请求\\n    setTimeout(() => {\\n      this.recommendList = this.getNewData()\\n      this.isRefreshing = false\\n    }, 2000)\\n  }\\n\\n  // 加载更多数据\\n  loadMoreData() {\\n    // 模拟加载更多\\n    setTimeout(() => {\\n      this.recommendList.push(...this.getMoreData())\\n    }, 1000)\\n  }\\n}\\n```\\n\\n### 🎬 最终实现效果\\n\\n通过以上步骤，我们成功实现了一个功能完整的多类型列表页面：\\n\\n**主要功能展示：**\\n\\n|                                                                                                                  下拉刷新 + 标题吸顶效果                                                                                                                  |                                                                                                                     上拉加载更多效果                                                                                                                      |\\n| :-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------: | :-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------: |\\n| ![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165822.96874077877710425089949009225341:50001231000000:2800:96C457F7A72CF6B38AD4AE6920F91C6BB82D2C7D1790C43151498ABB5895092B.gif) | ![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165822.43483295709730551222265753159402:50001231000000:2800:A9494A8B7DD1AA1743B970EF40CFBBEA859D6E85FED70D94FB3A5152936E44F1.gif) |\\n|                                                                                                  用户下拉时显示刷新动画，\\\"推荐景点\\\"标题在滚动时自动吸顶                                                                                                   |                                                                                                        滚动到底部时自动加载更多内容，提升用户体验                                                                                                         |\\n\\n**核心特性总结：**\\n\\n- ✅ **多类型内容**：轮播图、网格、列表完美融合\\n- ✅ **下拉刷新**：模拟真实的数据更新场景\\n- ✅ **上拉加载**：无限滚动，数据分页加载\\n- ✅ **标题吸顶**：重要信息始终可见\\n- ✅ **流畅交互**：符合用户操作习惯\\n\\n**适用场景回顾：**\\n这种实现方式特别适合需要展示丰富内容的首页场景，如电商 APP 首页、新闻资讯首页、旅游 APP 首页等。\\n\\n## Tabs 吸顶场景\\n\\n### 📖 场景说明\\n\\n**什么是 Tabs 吸顶效果？**\\n\\n想象一下你在使用今日头条、网易新闻等新闻 APP 时的体验：\\n\\n1. 页面顶部有搜索框和标题\\n2. 中间有分类标签（如\\\"推荐\\\"、\\\"热点\\\"、\\\"科技\\\"、\\\"娱乐\\\"等）\\n3. 下面是对应分类的新闻列表\\n4. **关键点**：当你向上滑动时，顶部内容会消失，但分类标签会\\\"粘\\\"在屏幕顶部不动\\n\\n这就是\\\"Tabs 吸顶\\\"效果！它让用户在浏览长列表时，依然能够方便地切换不同分类。\\n\\n**为什么需要这个效果？**\\n\\n- 🎯 **提升用户体验**：无论滚动到哪里，都能快速切换分类\\n- 📱 **节省屏幕空间**：隐藏不重要的顶部内容，留更多空间给内容\\n- 🔄 **符合使用习惯**：用户已经习惯了这种交互方式\\n\\n**常见应用场景：**\\n\\n- 📰 **新闻资讯 APP**：分类新闻浏览\\n- 🛒 **电商 APP**：商品分类浏览\\n- 🎵 **音乐 APP**：歌单分类\\n- 📺 **视频 APP**：内容分类\\n\\n### 🎯 本例效果预览\\n\\n我们将实现一个新闻资讯 APP 的首页，包含：\\n\\n1. **顶部区域**：搜索框、用户头像等（滚动时会隐藏）\\n2. **图片横幅**：热门新闻展示（滚动时会隐藏）\\n3. **Tabs 标签**：新闻分类导航（滚动时吸顶显示）\\n4. **内容列表**：对应分类的新闻列表（可正常滚动）\\n\\n|\\n页面整体结构图\\n\\n|\\n\\n页面效果图\\n\\n| |\\n| |\\n\\n|\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165822.62782711360682180824963975653408:50001231000000:2800:C347C757242C7B6FA3729F5A166E7162DB916AE4A16B80AAF93CD0028D46D3AC.png)\\n\\n|\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165823.62869979185221042136115433797699:50001231000000:2800:9492DEDCA09DABFD78964F6F2D265A996E999FD9DA99DA98441AEBD5724BC44C.png)\\n\\n|\\n\\n### 🔧 实现原理\\n\\n**核心思路：嵌套滚动 + 高度计算**\\n\\n实现 Tabs 吸顶的关键在于理解\\\"嵌套滚动\\\"的概念：\\n\\n```\\n页面结构：\\n┌─────────────────────┐\\n│   顶部搜索区域        │ ← 滚动时会隐藏\\n├─────────────────────┤\\n│   图片横幅区域        │ ← 滚动时会隐藏\\n├─────────────────────┤\\n│   Tabs标签区域       │ ← 滚动时吸顶（关键！）\\n├─────────────────────┤\\n│                     │\\n│   内容列表区域        │ ← 可以正常滚动\\n│   （新闻列表）        │\\n│                     │\\n└─────────────────────┘\\n```\\n\\n**技术实现要点：**\\n\\n1. **整体布局使用 Stack**：\\n\\n   - 底层：完整的页面内容（包括顶部区域）\\n   - 顶层：固定的 Tabs 标签（初始时透明或隐藏）\\n\\n2. **关键属性 - nestedScroll**：\\n\\n   ```typescript\\n   List().nestedScroll({\\n     scrollForward: NestedScrollMode.PARENT_FIRST, // 向上滚动时优先滚动父容器\\n     scrollBackward: NestedScrollMode.SELF_FIRST, // 向下滚动时优先滚动自己\\n   });\\n   ```\\n\\n3. **高度计算**：\\n   ```typescript\\n   // 计算Tabs应该显示的位置\\n   .height(`calc(100% - ${this.topHeight}px)`)\\n   ```\\n\\n**工作流程：**\\n\\n```\\n用户向上滚动 → 顶部内容逐渐隐藏 → 当滚动到Tabs位置时 → Tabs固定在顶部 → 继续滚动内容列表\\n```\\n\\n**关键组件说明：**\\n\\n- **[Tabs](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-tabs)**：标签页容器，提供分类切换功能\\n- **[Stack](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-stack)**：堆叠布局，实现层级效果\\n- **[List](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list)** + **[nestedScroll](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list#nestedscroll10)**：嵌套滚动的核心\\n- **[Scroll](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-scroll)**：滚动容器，承载顶部内容\\n\\n### 👨‍💻 开发步骤\\n\\n#### 步骤 1：创建自定义 Tabs 标签栏\\n\\n**目标：** 创建一个美观的分类标签栏，支持点击切换\\n\\n**关键点：**\\n\\n- 使用自定义 tabBar 而不是默认样式\\n- 支持滑动切换和点击切换\\n- 标签样式要清晰易识别\\n\\n```typescript\\n@Component\\nstruct CustomTabBar {\\n  @State currentIndex: number = 0\\n  private tabTitles: string[] = ['推荐', '热点', '科技', '娱乐', '体育']\\n\\n  build() {\\n    Row() {\\n      ForEach(this.tabTitles, (title: string, index: number) => {\\n        Column() {\\n          Text(title)\\n            .fontSize(16)\\n            .fontColor(this.currentIndex === index ? Color.Red : Color.Black)\\n            .fontWeight(this.currentIndex === index ? FontWeight.Bold : FontWeight.Normal)\\n\\n          // 底部指示线\\n          Divider()\\n            .width(20)\\n            .height(2)\\n            .color(Color.Red)\\n            .opacity(this.currentIndex === index ? 1 : 0)\\n            .margin({ top: 4 })\\n        }\\n        .layoutWeight(1)\\n        .padding({ vertical: 12 })\\n        .onClick(() => {\\n          this.currentIndex = index\\n          // 切换到对应标签页\\n        })\\n      })\\n    }\\n    .width('100%')\\n    .backgroundColor(Color.White)\\n  }\\n}\\n```\\n\\n**实现效果：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165823.88106166265057077238950701764329:50001231000000:2800:AAA1D34E3E23F512861AE12C30F6B1BF17CB3AECEDB0A9E8FB1674FBFE3B47FC.png)\\n\\n#### 步骤 2：创建顶部搜索区域\\n\\n**目标：** 实现顶部搜索框和用户信息区域（滚动时会隐藏）\\n\\n**关键点：**\\n\\n- 包含搜索框、用户头像、消息图标等\\n- 这部分内容在滚动时会被隐藏\\n- 布局要美观且功能完整\\n\\n```typescript\\n@Component\\nstruct TopSearchArea {\\n  build() {\\n    Row() {\\n      // 搜索框\\n      Row() {\\n        Image($r('app.media.search_icon'))\\n          .width(16)\\n          .height(16)\\n        Text('搜索新闻、资讯...')\\n          .fontSize(14)\\n          .fontColor(Color.Gray)\\n          .margin({ left: 8 })\\n      }\\n      .layoutWeight(1)\\n      .padding({ horizontal: 12, vertical: 8 })\\n      .backgroundColor('#F5F5F5')\\n      .borderRadius(20)\\n\\n      // 右侧图标\\n      Row() {\\n        Image($r('app.media.message_icon'))\\n          .width(24)\\n          .height(24)\\n          .margin({ right: 12 })\\n\\n        Image($r('app.media.avatar'))\\n          .width(32)\\n          .height(32)\\n          .borderRadius(16)\\n      }\\n      .margin({ left: 16 })\\n    }\\n    .width('100%')\\n    .padding(16)\\n    .backgroundColor(Color.White)\\n  }\\n}\\n```\\n\\n**实现效果：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165823.56399427082308676759105430344289:50001231000000:2800:95CE63575DAE9F450F501959598D2DBC1FEC03A508CB2C942C5AEC6B26FB1725.png)\\n\\n#### 步骤 3：创建图片横幅和内容列表\\n\\n**目标：** 添加热门新闻横幅和新闻列表内容\\n\\n**关键点：**\\n\\n- 横幅图片要吸引眼球\\n- 新闻列表要支持滚动\\n- 内容要丰富且布局合理\\n\\n```typescript\\n@Component\\nstruct NewsContent {\\n  @State newsList: NewsItem[] = []\\n\\n  build() {\\n    Column() {\\n      // 热门新闻横幅\\n      Image($r('app.media.hot_news_banner'))\\n        .width('100%')\\n        .height(200)\\n        .objectFit(ImageFit.Cover)\\n        .borderRadius(8)\\n        .margin(16)\\n\\n      // 新闻列表\\n      List() {\\n        ForEach(this.newsList, (news: NewsItem) => {\\n          ListItem() {\\n            Row() {\\n              Column() {\\n                Text(news.title)\\n                  .fontSize(16)\\n                  .fontWeight(FontWeight.Medium)\\n                  .maxLines(2)\\n                  .textOverflow({ overflow: TextOverflow.Ellipsis })\\n\\n                Text(news.summary)\\n                  .fontSize(14)\\n                  .fontColor(Color.Gray)\\n                  .maxLines(1)\\n                  .margin({ top: 4 })\\n\\n                Row() {\\n                  Text(news.source)\\n                    .fontSize(12)\\n                    .fontColor(Color.Gray)\\n                  Text(news.time)\\n                    .fontSize(12)\\n                    .fontColor(Color.Gray)\\n                    .margin({ left: 16 })\\n                }\\n                .margin({ top: 8 })\\n              }\\n              .layoutWeight(1)\\n              .alignItems(HorizontalAlign.Start)\\n\\n              Image(news.image)\\n                .width(80)\\n                .height(60)\\n                .borderRadius(4)\\n                .margin({ left: 12 })\\n            }\\n            .padding(16)\\n            .alignItems(VerticalAlign.Top)\\n          }\\n        })\\n      }\\n      .layoutWeight(1)\\n    }\\n  }\\n}\\n```\\n\\n**实现效果：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165823.43560829260439259522826638709868:50001231000000:2800:D8745FAA6D3EC3EF6D6D55A109C6370F61200DD60A7B6D6BEAB06811467E2E1E.png)\\n\\n#### 步骤 4：实现 Tabs 吸顶效果\\n\\n**目标：** 使用 nestedScroll 属性实现 Tabs 标签的吸顶效果\\n\\n**关键点：**\\n\\n- 使用 Stack 布局实现层级效果\\n- 配置 nestedScroll 属性\\n- 计算正确的高度值\\n\\n```typescript\\n@Component\\nstruct TabsStickyPage {\\n  @State topHeight: number = 200 // 顶部区域高度\\n\\n  build() {\\n    Stack({ alignContent: Alignment.Top }) {\\n      // 底层：完整页面内容\\n      Column() {\\n        TopSearchArea()        // 顶部搜索区域\\n\\n        Tabs() {\\n          TabContent() {\\n            NewsContent()      // 推荐新闻内容\\n          }.tabBar('推荐')\\n\\n          TabContent() {\\n            NewsContent()      // 热点新闻内容\\n          }.tabBar('热点')\\n\\n          // 更多标签页...\\n        }\\n        .barPosition(BarPosition.Start)\\n        .layoutWeight(1)\\n      }\\n\\n      // 顶层：固定的Tabs标签（吸顶时显示）\\n      Column() {\\n        CustomTabBar()\\n      }\\n      .width('100%')\\n      .position({ x: 0, y: this.topHeight })\\n      .zIndex(1)\\n\\n      // 内容区域List（关键：配置nestedScroll）\\n      List() {\\n        // 内容项...\\n      }\\n      .nestedScroll({\\n        scrollForward: NestedScrollMode.PARENT_FIRST,\\n        scrollBackward: NestedScrollMode.SELF_FIRST\\n      })\\n      .height(`calc(100% - ${this.topHeight}px)`)\\n      .margin({ top: this.topHeight })\\n    }\\n    .width('100%')\\n    .height('100%')\\n  }\\n}\\n```\\n\\n**核心配置说明：**\\n\\n- `NestedScrollMode.PARENT_FIRST`：向上滚动时优先滚动父容器（隐藏顶部内容）\\n- `NestedScrollMode.SELF_FIRST`：向下滚动时优先滚动自己（显示顶部内容）\\n- `calc(100% - ${this.topHeight}px)`：动态计算内容区域高度\\n\\n### 🎬 最终实现效果\\n\\n通过以上步骤，我们成功实现了 Tabs 吸顶的完整效果：\\n\\n**核心功能展示：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165823.91018368051381725848392660977082:50001231000000:2800:50562907B49B1D6FCC27E5A6FD1C14145BEF945099657614F782CD438F2BD716.gif)\\n\\n**效果说明：**\\n\\n1. **初始状态**：顶部搜索区域、图片横幅、Tabs 标签都正常显示\\n2. **向上滚动**：顶部内容逐渐隐藏，Tabs 标签开始上移\\n3. **吸顶状态**：Tabs 标签固定在屏幕顶部，内容列表继续滚动\\n4. **向下滚动**：Tabs 标签回到原位，顶部内容重新显示\\n\\n**技术特点总结：**\\n\\n- ✅ **流畅的滚动体验**：使用 nestedScroll 实现自然的滚动效果\\n- ✅ **精确的吸顶定位**：通过高度计算确保 Tabs 准确吸顶\\n- ✅ **完整的交互功能**：支持标签切换和内容滚动\\n- ✅ **良好的用户体验**：符合主流 APP 的交互习惯\\n\\n**适用场景回顾：**\\n这种 Tabs 吸顶效果特别适合内容分类较多的应用，如新闻资讯、电商分类、视频分类等场景，能够显著提升用户的浏览效率。\\n\\n## 分组吸顶场景\\n\\n### 📖 场景说明\\n\\n**什么是分组吸顶效果？**\\n\\n这是一个非常实用的功能，最典型的例子就是手机通讯录：\\n\\n1. 联系人按照姓名首字母分组（A、B、C、D...）\\n2. 右侧有一个字母索引条（A-Z）\\n3. 滚动时，当前分组的字母标题会\\\"吸\\\"在顶部\\n4. 点击右侧字母，左侧列表会快速跳转到对应分组\\n5. 滚动左侧列表时，右侧对应字母会高亮显示\\n\\n**为什么需要这个效果？**\\n\\n- 🔍 **快速定位**：在大量数据中快速找到目标内容\\n- 📍 **位置感知**：用户始终知道当前浏览到哪个分组\\n- ⚡ **高效导航**：一键跳转到任意分组\\n- 👀 **视觉清晰**：分组标题吸顶，分类一目了然\\n\\n**常见应用场景：**\\n\\n- 📞 **通讯录**：按姓名首字母分组的联系人列表\\n- 🏙️ **城市选择**：按首字母分组的城市列表\\n- 🏢 **公司选择**：按首字母分组的公司列表\\n- 📚 **词典应用**：按首字母分组的词汇列表\\n- 🎵 **音乐列表**：按歌手首字母分组的歌曲\\n\\n### 🎯 本例效果预览\\n\\n我们将实现一个城市选择页面，包含：\\n\\n1. **左侧城市列表**：\\n\\n   - 当前城市（定位获取）\\n   - 热门城市（常用城市）\\n   - 按字母分组的所有城市（A-Z）\\n   - 分组标题支持吸顶效果\\n\\n2. **右侧字母索引**：\\n\\n   - A-Z 字母快速导航\\n   - 当前分组字母高亮显示\\n   - 点击字母快速跳转\\n\\n3. **双向联动效果**：\\n   - 滚动左侧列表 → 右侧字母高亮变化\\n   - 点击右侧字母 → 左侧列表跳转到对应分组\\n\\n|\\n页面整体结构图\\n\\n|\\n\\n页面效果图\\n\\n| |\\n| |\\n\\n|\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165823.26005999220251986715837607641233:50001231000000:2800:1C2F35BE513654E26CCA24B7232E6F0F3EC565D7BA60DE7BFD5D90C0C92B78D3.png)\\n\\n|\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165823.86784006847319368945817111834563:50001231000000:2800:DF526D9C2A987672415A87CA36DE1E1AB305C1709397D2006BCF77818E16D16E.png)\\n\\n|\\n\\n### 🔧 实现原理详解\\n\\n**核心思想：分组 + 吸顶 + 双向联动**\\n\\n想象一下，我们要实现的效果就像是一个\\\"智能书签系统\\\"：\\n\\n- 📚 **书本**：整个城市列表\\n- 🏷️ **书签**：每个字母分组的标题\\n- 📍 **智能吸顶**：当前章节的书签始终显示在顶部\\n- 🔗 **快速索引**：右侧字母导航就像目录，点击直接跳转\\n\\n**技术架构图：**\\n\\n```\\nStack (堆叠布局)\\n├── 左侧城市列表 (List)\\n│   ├── ListItemGroup (当前城市)\\n│   │   ├── 分组标题 (sticky吸顶)\\n│   │   └── 城市项目 (ListItem)\\n│   ├── ListItemGroup (热门城市)\\n│   │   ├── 分组标题 (sticky吸顶)\\n│   │   └── 城市项目 (ListItem)\\n│   └── ListItemGroup (A-Z分组)\\n│       ├── 分组标题 (sticky吸顶)\\n│       └── 城市项目 (ListItem)\\n└── 右侧字母索引 (List)\\n    ├── 字母A (ListItem)\\n    ├── 字母B (ListItem)\\n    └── ...\\n```\\n\\n**关键技术组件：**\\n\\n| 组件              | 作用     | 关键属性/方法                    | 说明                          |\\n| ----------------- | -------- | -------------------------------- | ----------------------------- |\\n| **ListItemGroup** | 分组容器 | `sticky: StickyStyle.Header`     | 实现分组标题吸顶效果          |\\n| **Stack**         | 布局容器 | 分层显示                         | 左侧列表 + 右侧索引的叠加布局 |\\n| **List**          | 列表容器 | `onScrollIndex`、`scrollToIndex` | 监听滚动、控制跳转            |\\n| **ListItem**      | 列表项   | 数据展示                         | 城市信息的具体展示            |\\n\\n**核心技术点详解：**\\n\\n1. **🎯 分组吸顶机制**：\\n\\n   ```typescript\\n   ListItemGroup({ sticky: StickyStyle.Header }) {\\n     // 分组标题 - 会自动吸顶\\n     // 分组内容 - 正常滚动\\n   }\\n   ```\\n\\n2. **📡 滚动监听机制**：\\n\\n   ```typescript\\n   List() {\\n     // 监听滚动位置变化\\n     .onScrollIndex((start, end) => {\\n       // 根据当前显示的项目更新右侧字母高亮\\n     })\\n   }\\n   ```\\n\\n3. **⚡ 快速跳转机制**：\\n   ```typescript\\n   // 点击右侧字母时\\n   this.listController.scrollToIndex(targetIndex);\\n   ```\\n\\n**工作流程：**\\n\\n1. **初始化**：构建分组数据，计算每个分组的起始索引\\n2. **滚动监听**：实时监听列表滚动位置\\n3. **状态同步**：根据滚动位置更新右侧字母高亮\\n4. **快速跳转**：点击字母时跳转到对应分组\\n5. **吸顶显示**：当前分组标题自动吸顶\\n\\n### 🛠️ 开发步骤详解\\n\\n#### 步骤 1：构建数据结构 📊\\n\\n**目标**：创建完整的城市数据结构，支持分组和索引\\n\\n**关键实现点**：\\n\\n- 定义城市数据模型\\n- 构建当前城市、热门城市、字母分组数据\\n- 计算每个分组的起始索引位置\\n\\n**核心代码示例**：\\n\\n```typescript\\n// 城市数据模型\\ninterface CityInfo {\\n  name: string;\\n  code?: string;\\n}\\n\\n// 分组数据结构\\ninterface CityGroup {\\n  title: string;\\n  cities: CityInfo[];\\n  startIndex: number; // 在整个列表中的起始位置\\n}\\n\\n// 构建完整数据\\nconst cityData = {\\n  current: { title: \\\"当前城市\\\", cities: [currentCity] },\\n  hot: { title: \\\"热门城市\\\", cities: hotCities },\\n  groups: alphabetGroups, // A-Z分组\\n};\\n```\\n\\n**视觉效果**：数据结构清晰，为后续功能奠定基础\\n\\n---\\n\\n#### 步骤 2：创建 Stack 分层布局 🏗️\\n\\n**目标**：使用 Stack 组件实现左右分层显示\\n\\n**关键实现点**：\\n\\n- Stack 容器包含左侧城市列表和右侧字母索引\\n- 右侧字母索引悬浮在左侧列表之上\\n- 合理设置对齐方式和层级关系\\n\\n**核心代码示例**：\\n\\n```typescript\\nStack({ alignContent: Alignment.End }) {\\n  // 左侧城市列表（底层）\\n  List() {\\n    // 城市列表内容\\n  }\\n  .width('100%')\\n  .height('100%')\\n\\n  // 右侧字母索引（顶层）\\n  List() {\\n    // 字母导航内容\\n  }\\n  .width('30vp')\\n  .height('100%')\\n}\\n```\\n\\n**视觉效果**：左右布局清晰，字母索引悬浮显示\\n\\n---\\n\\n#### 步骤 3：实现左侧分组列表 📋\\n\\n**目标**：使用 ListItemGroup 创建支持吸顶的分组列表\\n\\n**关键实现点**：\\n\\n- 使用 ListItemGroup 包装每个分组\\n- 设置 sticky 属性实现标题吸顶\\n- 渲染当前城市、热门城市、字母分组\\n\\n**核心代码示例**：\\n\\n```typescript\\nList() {\\n  // 当前城市分组\\n  ListItemGroup({\\n    header: this.groupHeader('当前城市'),\\n    sticky: StickyStyle.Header\\n  }) {\\n    ForEach(currentCities, (city) => {\\n      ListItem() {\\n        this.cityItem(city)\\n      }\\n    })\\n  }\\n\\n  // 热门城市分组\\n  ListItemGroup({\\n    header: this.groupHeader('热门城市'),\\n    sticky: StickyStyle.Header\\n  }) {\\n    // 热门城市内容\\n  }\\n\\n  // A-Z字母分组\\n  ForEach(alphabetGroups, (group) => {\\n    ListItemGroup({\\n      header: this.groupHeader(group.title),\\n      sticky: StickyStyle.Header\\n    }) {\\n      // 分组城市内容\\n    }\\n  })\\n}\\n```\\n\\n**视觉效果**：分组清晰，标题支持吸顶显示\\n\\n---\\n\\n#### 步骤 4：创建右侧字母索引 🔤\\n\\n**目标**：实现可点击的字母导航，支持快速跳转\\n\\n**关键实现点**：\\n\\n- 渲染 A-Z 字母列表\\n- 监听字母点击事件\\n- 实现高亮状态切换\\n- 调用 scrollToIndex 跳转到对应分组\\n\\n**核心代码示例**：\\n\\n```typescript\\nList() {\\n  ForEach(alphabetList, (letter, index) => {\\n    ListItem() {\\n      Text(letter)\\n        .fontSize(12)\\n        .fontColor(this.currentLetter === letter ? '#007DFF' : '#666')\\n        .fontWeight(this.currentLetter === letter ? 600 : 400)\\n    }\\n    .onClick(() => {\\n      // 跳转到对应分组\\n      const targetIndex = this.getGroupStartIndex(letter);\\n      this.listController.scrollToIndex(targetIndex);\\n      this.currentLetter = letter;\\n    })\\n  })\\n}\\n```\\n\\n**视觉效果**：字母导航清晰，点击有反馈，支持快速跳转\\n\\n---\\n\\n#### 步骤 5：实现双向联动效果 🔄\\n\\n**目标**：滚动左侧列表时，右侧字母自动高亮；点击右侧字母时，左侧列表跳转\\n\\n**关键实现点**：\\n\\n- 监听 onScrollIndex 事件\\n- 根据当前显示区域计算对应字母\\n- 更新右侧字母高亮状态\\n- 实现平滑的联动效果\\n\\n**核心代码示例**：\\n\\n```typescript\\nList() {\\n  // 城市列表内容\\n}\\n.onScrollIndex((start, end) => {\\n  // 根据当前显示的索引范围，计算对应的字母分组\\n  const currentGroup = this.getCurrentGroupByIndex(start);\\n  if (currentGroup && this.currentLetter !== currentGroup.title) {\\n    this.currentLetter = currentGroup.title;\\n  }\\n})\\n```\\n\\n**视觉效果**：滚动流畅，字母高亮准确，用户体验良好\\n\\n**相关文档链接**：\\n\\n- [sticky 属性文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list#sticky9)\\n- [onScrollIndex 方法文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list#onscrollindex)\\n- [scrollToIndex 方法文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-scroll#scrolltoindex)\\n\\n### 🎬 最终实现效果\\n\\n通过以上步骤，我们成功实现了分组吸顶的完整功能：\\n\\n**核心功能展示：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165823.84849940052638703591947817896703:50001231000000:2800:676D4CB64CC02C60DF52288D60A8C9012339CD99D0BECEA27D64EA32B4FF93DE.gif)\\n\\n**效果说明：**\\n\\n1. **分组显示**：城市按照\\\"当前城市\\\"、\\\"热门城市\\\"、\\\"A-Z 字母\\\"清晰分组\\n2. **吸顶效果**：滚动时，当前分组标题自动吸附在顶部\\n3. **字母索引**：右侧 A-Z 字母导航，当前分组字母高亮显示\\n4. **快速跳转**：点击右侧字母，左侧列表立即跳转到对应分组\\n5. **双向联动**：滚动左侧列表，右侧字母高亮状态实时更新\\n\\n**技术特点总结：**\\n\\n- ✅ **智能分组**：支持多种分组类型（当前、热门、字母）\\n- ✅ **精准吸顶**：ListItemGroup 的 sticky 属性确保标题准确吸顶\\n- ✅ **快速导航**：字母索引提供一键跳转功能\\n- ✅ **实时联动**：滚动和点击事件完美同步\\n- ✅ **用户友好**：符合用户对通讯录等应用的使用习惯\\n\\n**适用场景回顾：**\\n这种分组吸顶效果广泛应用于需要大量数据分类展示的场景，如通讯录、城市选择、公司列表等，能够显著提升用户查找效率和使用体验。\\n\\n**性能优势：**\\n\\n- 🚀 **高效渲染**：List 组件的虚拟滚动确保大数据量下的流畅性能\\n- 💾 **内存优化**：只渲染可见区域的列表项，节省内存占用\\n- ⚡ **快速响应**：原生组件确保交互响应速度\\n\\n## 二级联动场景\\n\\n### 📖 场景说明\\n\\n**什么是二级联动效果？**\\n\\n这是一个经典的\\\"主从\\\"关系界面，最常见的例子就是电商 APP 的商品分类页面：\\n\\n1. **左侧一级分类**：显示主要分类（如\\\"服装\\\"、\\\"数码\\\"、\\\"家居\\\"等）\\n2. **右侧二级分类**：显示选中一级分类下的子分类\\n3. **联动关系**：点击左侧分类 → 右侧内容立即更新\\n4. **反向联动**：滚动右侧内容 → 左侧对应分类高亮\\n5. **吸顶效果**：右侧列表的分组标题支持吸顶显示\\n\\n**为什么需要这个效果？**\\n\\n- 🎯 **层级清晰**：将复杂的分类体系分解为两个层级，降低认知负担\\n- 🔄 **高效导航**：左侧提供快速分类切换，右侧展示详细内容\\n- 👀 **状态同步**：用户始终知道当前浏览的是哪个分类\\n- 📱 **空间利用**：充分利用屏幕空间，展示更多信息\\n\\n**常见应用场景：**\\n\\n- 🛒 **电商分类**：商品的一级分类和二级分类选择\\n- 🎨 **编辑工具**：风格分类和具体风格选择\\n- 📚 **内容分类**：文章分类和子分类浏览\\n- 🏢 **组织架构**：部门和子部门的层级展示\\n- 🎵 **音乐分类**：音乐类型和具体歌单分类\\n- 🍔 **餐饮菜单**：菜品分类和具体菜品展示\\n\\n### 🎯 本例效果预览\\n\\n我们将实现一个商品分类选择页面，包含：\\n\\n1. **左侧一级分类导航**：\\n\\n   - 垂直排列的主要分类列表\\n   - 当前选中分类高亮显示\\n   - 点击切换分类功能\\n\\n2. **右侧二级内容区域**：\\n\\n   - 显示选中分类的详细子分类\\n   - 支持分组标题吸顶效果\\n   - 丰富的内容展示（图片+文字）\\n\\n3. **双向联动机制**：\\n   - **主动联动**：点击左侧分类 → 右侧内容切换\\n   - **被动联动**：滚动右侧内容 → 左侧分类高亮更新\\n   - **状态保持**：切换分类时保持滚动位置\\n\\n### 🏗️ 页面结构设计\\n\\n**整体布局架构：**\\n\\n| 页面整体结构图                                                                                                                                                                                                                                            | 页面效果图                                                                                                                                                                                                                                                |\\n| --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- | --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| ![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165824.02038841658173170488267671898697:50001231000000:2800:C7E17AEE209649A3D1282C8B5722F4E182B44CAEEA98EF20957CD2A0AC4A31B6.png) | ![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165824.63775411051017192052366887335981:50001231000000:2800:4B84E9490CE740500E646579C4937C81EE72497870AC28C9FAA1A0E533291501.png) |\\n| **左右分栏布局**：左侧导航 + 右侧内容                                                                                                                                                                                                                     | **实际效果**：清晰的分类层级和丰富的内容展示                                                                                                                                                                                                              |\\n\\n### 🔧 实现原理详解\\n\\n**核心思想：双 List 联动 + 状态同步**\\n\\n想象一下，这就像是一个\\\"智能目录系统\\\"：\\n\\n- 📖 **左侧目录**：显示章节标题，点击可快速跳转\\n- 📄 **右侧内容**：显示具体内容，滚动时目录自动跟随\\n- 🔗 **智能联动**：目录和内容始终保持同步\\n\\n**技术架构：**\\n\\n```\\nRow (水平布局)\\n├── 左侧导航区域 (List)\\n│   ├── 分类1 (ListItem) - 可点击\\n│   ├── 分类2 (ListItem) - 可点击\\n│   └── 分类N (ListItem) - 可点击\\n└── 右侧内容区域 (List)\\n    ├── ListItemGroup (分类1内容)\\n    │   ├── 分组标题 (sticky吸顶)\\n    │   └── 子分类项目 (ListItem)\\n    ├── ListItemGroup (分类2内容)\\n    └── ListItemGroup (分类N内容)\\n```\\n\\n**关键技术点：**\\n\\n1. **🎯 双向监听机制**：\\n\\n   - 左侧 List 监听点击事件 → 控制右侧 List 跳转\\n   - 右侧 List 监听滚动事件 → 更新左侧 List 高亮\\n\\n2. **📡 状态同步算法**：\\n\\n   ```typescript\\n   // 右侧滚动时，计算当前显示的分类\\n   .onScrollIndex((start, end) => {\\n     const currentCategory = this.getCategoryByIndex(start);\\n     this.updateLeftHighlight(currentCategory);\\n   })\\n   ```\\n\\n3. **⚡ 精准跳转控制**：\\n   ```typescript\\n   // 左侧点击时，跳转到对应分类\\n   .onClick(() => {\\n     const targetIndex = this.getCategoryStartIndex(category);\\n     this.rightListController.scrollToIndex(targetIndex);\\n   })\\n   ```\\n\\n**相关文档链接**：\\n\\n- [onScrollIndex 事件文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list#onscrollindex)\\n- [scrollToIndex 方法文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-scroll#scrolltoindex)\\n\\n### 🛠️ 开发步骤详解\\n\\n#### 步骤 1：构建数据结构 📊\\n\\n**目标**：创建支持二级联动的分类数据结构\\n\\n**关键实现点**：\\n\\n- 定义一级分类和二级分类的数据模型\\n- 建立分类之间的映射关系\\n- 计算每个分类在右侧列表中的起始位置\\n\\n**核心代码示例**：\\n\\n```typescript\\n// 分类数据模型\\ninterface Category {\\n  id: string;\\n  name: string;\\n  icon?: string;\\n  subCategories: SubCategory[];\\n  startIndex: number; // 在右侧列表中的起始位置\\n}\\n\\ninterface SubCategory {\\n  id: string;\\n  name: string;\\n  image?: string;\\n  description?: string;\\n}\\n\\n// 构建完整的分类数据\\nconst categoryData: Category[] = [\\n  {\\n    id: '1',\\n    name: '服装鞋帽',\\n    subCategories: [...],\\n    startIndex: 0\\n  },\\n  // 更多分类...\\n];\\n```\\n\\n#### 步骤 2：创建左右分栏布局 🏗️\\n\\n**目标**：使用 Row 组件实现左右分栏显示\\n\\n**关键实现点**：\\n\\n- Row 容器包含左侧导航和右侧内容\\n- 合理分配左右区域的宽度比例\\n- 设置合适的分割线或背景色区分\\n\\n**核心代码示例**：\\n\\n```typescript\\nRow() {\\n  // 左侧分类导航\\n  List() {\\n    ForEach(categories, (category) => {\\n      ListItem() {\\n        this.categoryNavItem(category)\\n      }\\n      .onClick(() => this.onCategoryClick(category))\\n    })\\n  }\\n  .width('25%')\\n  .backgroundColor('#F5F5F5')\\n\\n  // 右侧内容区域\\n  List() {\\n    ForEach(categories, (category) => {\\n      ListItemGroup({\\n        header: this.categoryHeader(category.name),\\n        sticky: StickyStyle.Header\\n      }) {\\n        ForEach(category.subCategories, (subCategory) => {\\n          ListItem() {\\n            this.subCategoryItem(subCategory)\\n          }\\n        })\\n      }\\n    })\\n  }\\n  .width('75%')\\n  .onScrollIndex((start, end) => this.onRightScroll(start, end))\\n}\\n```\\n\\n#### 步骤 3：实现联动控制逻辑 🔄\\n\\n**目标**：实现左右列表的双向联动效果\\n\\n**关键实现点**：\\n\\n- 左侧点击事件处理\\n- 右侧滚动事件监听\\n- 状态同步和高亮更新\\n- 防抖处理避免频繁更新\\n\\n**核心代码示例**：\\n\\n```typescript\\n// 左侧分类点击处理\\nonCategoryClick(category: Category) {\\n  this.currentCategoryId = category.id;\\n  this.rightListController.scrollToIndex(category.startIndex);\\n}\\n\\n// 右侧列表滚动处理\\nonRightScroll(start: number, end: number) {\\n  const currentCategory = this.getCategoryByIndex(start);\\n  if (currentCategory && this.currentCategoryId !== currentCategory.id) {\\n    this.currentCategoryId = currentCategory.id;\\n  }\\n}\\n\\n// 根据索引获取对应分类\\ngetCategoryByIndex(index: number): Category | null {\\n  for (const category of this.categories) {\\n    const endIndex = category.startIndex + category.subCategories.length;\\n    if (index >= category.startIndex && index < endIndex) {\\n      return category;\\n    }\\n  }\\n  return null;\\n}\\n```\\n\\n### 🎬 最终实现效果\\n\\n通过以上步骤，我们成功实现了二级联动的完整功能：\\n\\n**核心功能展示：**\\n\\n![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250613165824.24803321986473082086044805634677:50001231000000:2800:474AC93597B2A3E2723F4043DF234FE657A0E5A094ADFC6CEBF8B0EBDBF078A7.gif)\\n\\n**效果说明：**\\n\\n1. **分类导航**：左侧显示主要分类，当前选中分类高亮显示\\n2. **内容展示**：右侧显示选中分类的详细子分类内容\\n3. **主动联动**：点击左侧分类，右侧内容立即切换到对应分类\\n4. **被动联动**：滚动右侧内容，左侧分类高亮状态自动更新\\n5. **吸顶效果**：右侧分组标题支持吸顶显示，提升浏览体验\\n\\n**技术特点总结：**\\n\\n- ✅ **响应迅速**：点击和滚动事件响应及时，用户体验流畅\\n- ✅ **状态同步**：左右两侧状态始终保持一致\\n- ✅ **视觉清晰**：分类层级清晰，内容组织有序\\n- ✅ **交互友好**：符合用户对分类选择界面的使用习惯\\n- ✅ **性能优化**：使用 List 组件的虚拟滚动，支持大量数据展示\\n\\n**适用场景总结：**\\n这种二级联动效果特别适合需要展示层级分类数据的场景，如电商分类、内容分类、组织架构等，能够帮助用户快速定位和浏览目标内容，显著提升应用的易用性和用户满意度。\\n\\n---\\n\\n## 🎓 学习总结与进阶指南\\n\\n### 📚 知识点回顾\\n\\n通过本教程，你已经掌握了：\\n\\n| 技能等级   | 掌握内容                                     | 实用性     |\\n| ---------- | -------------------------------------------- | ---------- |\\n| **基础级** | List、ListItem、Image、Text 等基础组件       | ⭐⭐⭐⭐⭐ |\\n| **进阶级** | Swiper 轮播、Grid 网格、下拉刷新             | ⭐⭐⭐⭐   |\\n| **高级级** | sticky 吸顶、nestedScroll 嵌套滚动、双向联动 | ⭐⭐⭐     |\\n\\n### 🚀 实战建议\\n\\n**立即可以做的项目：**\\n\\n1. 📱 **仿淘宝首页**：应用多类型列表项技能\\n2. 📰 **新闻 APP**：使用 Tabs 吸顶功能\\n3. 📞 **通讯录应用**：练习分组吸顶效果\\n4. 🛒 **购物分类页**：实现二级联动\\n\\n**进阶学习方向：**\\n\\n- 🎨 **动画效果**：为列表添加炫酷的过渡动画\\n- 🔄 **状态管理**：学习复杂数据的状态管理\\n- 🌐 **网络请求**：结合真实 API 接口获取数据\\n- 📱 **响应式设计**：适配不同尺寸的设备\\n\\n### 💡 开发小贴士\\n\\n**性能优化：**\\n\\n- ✅ 列表数据较多时，List 组件会自动进行虚拟滚动优化\\n- ✅ 图片建议使用适当尺寸，避免内存浪费\\n- ✅ 合理使用@State 状态管理，避免不必要的重新渲染\\n\\n**调试技巧：**\\n\\n- 🐛 使用`console.log()`输出调试信息\\n- 🐛 利用 DevEco Studio 的预览功能实时查看效果\\n- 🐛 善用官方文档和示例代码\\n\\n**代码规范：**\\n\\n- 📝 组件名称使用大驼峰命名（如 SearchHeader）\\n- 📝 添加有意义的注释，方便后续维护\\n- 📝 保持代码结构清晰，一个组件完成一个功能\\n\\n### 📖 相关资源\\n\\n**官方文档：**\\n\\n- 🔗 [List 组件详细文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list)\\n- 🔗 [HarmonyOS 开发指南](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/start-overview)\\n- 🔗 [ArkTS 语法参考](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-get-started)\\n\\n**学习社区：**\\n\\n- 👥 [HarmonyOS 开发者论坛](https://developer.huawei.com/consumer/cn/forum/block/harmonyos)\\n- 📺 [官方视频教程](https://developer.huawei.com/consumer/cn/training/)\\n\\n### 🎯 下一步学习建议\\n\\n1. **巩固基础**：多敲代码，熟练掌握基础组件\\n2. **实战练习**：选择一个感兴趣的 APP 界面进行仿制\\n3. **深入学习**：探索更多高级组件和 API\\n4. **参与社区**：加入开发者群体，交流学习心得\\n\\n> 🌟 **记住**：编程是一个不断实践和提升的过程，每写一行代码都是在进步！加油！\\n\\n> 如果这篇文章对你有帮助，欢迎点赞、收藏和分享！有问题欢迎在评论区讨论～\\n\"}"),p={name:"HarmonyOS 最佳实践/07-常见列表操作/07-常见列表操作.md"};function t(e,s,h,r,k,E){return i(),a("div",null,[...s[0]||(s[0]=[l("",361)])])}const c=n(p,[["render",t]]);export{g as __pageData,c as default};
